import{_ as e,o as r,c as t,ae as i}from"./chunks/framework.Co1PSFSm.js";const u=JSON.parse('{"title":"介绍","description":"Fresh 框架介绍","frontmatter":{"description":"Fresh 框架介绍"},"headers":[],"relativePath":"zh/introduction/index.md","filePath":"zh/introduction/index.md"}'),o={name:"zh/introduction/index.md"};function n(l,a,h,s,c,d){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><p>Fresh 是 Deno 的下一代 Web 框架。它具有以下特点：</p><ul><li><strong>零配置</strong>：无需复杂的配置文件，开箱即用</li><li><strong>岛屿架构</strong>：只在需要交互的地方运行 JavaScript</li><li><strong>服务端优先</strong>：默认在服务端渲染页面</li><li><strong>快速响应</strong>：极小的 JavaScript 捆绑包，最小的加载时间</li></ul><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>Fresh 基于以下核心技术：</p><ul><li><strong>Deno</strong>：现代的 JavaScript 和 TypeScript 运行时</li><li><strong>Preact</strong>：轻量级 React 替代品</li><li><strong>Vite</strong>：快速的开发服务器和构建工具</li><li><strong>TypeScript</strong>：静态类型检查</li></ul><h2 id="为什么选择-fresh" tabindex="-1">为什么选择 Fresh？ <a class="header-anchor" href="#为什么选择-fresh" aria-label="Permalink to &quot;为什么选择 Fresh？&quot;">​</a></h2><h3 id="_1-极致的性能" tabindex="-1">1. 极致的性能 <a class="header-anchor" href="#_1-极致的性能" aria-label="Permalink to &quot;1. 极致的性能&quot;">​</a></h3><p>Fresh 默认在服务端渲染页面，确保用户能够快速看到内容。客户端只需要加载页面所需的最小 JavaScript。</p><h3 id="_2-岛屿架构" tabindex="-1">2. 岛屿架构 <a class="header-anchor" href="#_2-岛屿架构" aria-label="Permalink to &quot;2. 岛屿架构&quot;">​</a></h3><p>Fresh 的岛屿架构让您可以精确控制页面的交互性。只有标记为 island 的组件才会发送 JavaScript 到客户端，其他内容保持静态 HTML。</p><h3 id="_3-简洁的开发体验" tabindex="-1">3. 简洁的开发体验 <a class="header-anchor" href="#_3-简洁的开发体验" aria-label="Permalink to &quot;3. 简洁的开发体验&quot;">​</a></h3><p>无需复杂的配置，无需构建步骤。您可以直接编写代码，Fresh 会处理其余的事情。</p><h3 id="_4-完整的类型安全" tabindex="-1">4. 完整的类型安全 <a class="header-anchor" href="#_4-完整的类型安全" aria-label="Permalink to &quot;4. 完整的类型安全&quot;">​</a></h3><p>Fresh 使用 TypeScript 开发，提供完整的类型检查和智能提示。</p><h2 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to &quot;开始使用&quot;">​</a></h2><p>要创建您的第一个 Fresh 项目，请查看 <a href="/zh/getting-started/">快速开始指南</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/zh/concepts/architecture.html">核心概念</a> - 了解 Fresh 的工作原理</li><li><a href="/zh/concepts/islands.html">岛屿</a> - 学习如何创建交互式组件</li><li><a href="/zh/concepts/routing.html">路由</a> - 了解如何处理不同的 URL</li></ul>',19)])])}const _=e(o,[["render",n]]);export{u as __pageData,_ as default};
